function K-Commit($l,[string]$tracePath){
# No external loader, current Source fence, legacy history or nonnegative eligibility.
Assert-LedgerOwner $script:ledgerTransaction;$state=K-Validate $l;$traceSpec=Pin $tracePath;$t=K-Read $traceSpec 2097152;Same $t.schema 'flylab.m3.direct-science.genuine-return.v1' 'Actual collector';Same $t.phase 'FINAL' 'First FINAL';Same $t.first_error $null 'No uncertain collector';$null=K-Int $t.dispatch_ms $true;$null=K-Int $t.first_final_ms $true;[double]$seconds=($t.first_final_ms-$t.dispatch_ms)/1000.0;Need ((K-Number $seconds) -gt 0) 'Finite genuine fee';Same $t.full_return_s $seconds 'Exact genuine elapsed';$q=K-Read $t.request;$call=$q.call_id;$null=K-Identity $q $t.request $state.source
Need ($l.direct_science_calls.Contains($call) -and $l.direct_science_calls[$call].state -ceq 'admitted' -and $call -cnotin @($l.debits.cost_id)) 'Actual once call';Same $l.direct_science_calls[$call].request $t.request 'Same admitted owner';Same $t.source_freeze $state.source 'Intact execution Source binding';$outerSpec=Pin ($q.output+'/outer.json');$o=K-Read $outerSpec 1048576;Same $o.request $t.request 'Actual supervisor outer';Need (K-ExitMatch $t $o $t.request) 'Same observed exit or proven shell pair';$closed=K-Closure $o;if(-not $closed){return @{committed=$false;status='UNCOMMITTED_OWNERSHIP_UNKNOWN';trace=$traceSpec;outer=$outerSpec;actual_s=$seconds;cost_published=$false;owner_and_reservation_retained=$true}}
$cost=@{schema='flylab.m3.direct-science.full-return.v1';cost_id=$call;mode=$q.mode;request=$t.request;source_freeze=$t.source_freeze;trace=$traceSpec;outer=$outerSpec;actual_outer_full_return_s=$seconds;exit_code=$t.exit_code;charged_once=$true;all_owned_ended=$o.all_owned_ended;reservation_released=$o.reservation_released;cap_exceeded=($seconds -gt $q.limits.outer_s);worker_started=$o.worker_started;worker_creation_state=$o.worker_creation_state;creation_attempted=$o.creation_attempted;resume_attempted=$o.resume_attempted;resume_outcome=$o.resume_outcome}
if($o.exit_code -ne $t.exit_code){$cost.native_supervisor_exit_code=$o.exit_code;$cost.actual_collector_shell_exit_code=$t.exit_code;$cost.shell_deadline_status_pair_observed=$true};if($q.mode -ceq 'original'){$science=K-Read $q.science_request;$cost.schema='flylab.m3.contact-learning.full-return.v1';$cost.request=$q.science_request;$cost.supervisor_request=$t.request;foreach($k in @('role','grant','inputs','roster','contract','body_retry','local_debit_offset','resource_increment_s')){$cost[$k]=$science[$k]}}
$costName=$taskBase+'/parent-'+$call+'-full-return.json';if([IO.File]::Exists((Safe $costName))){$costSpec=Pin $costName;Same (K-Read $costSpec) $cost 'Only exact existing uncommitted cost'}else{$costSpec=Write-New $costName $cost}
$d=@{cost_id=$call;mode=$q.mode;actual_outer_full_return_s=$seconds;actual_returned_exit_code=$t.exit_code;descriptor=$costSpec};$null=K-FeeProof $costSpec $d $state.source;$l.debits+=@($d);$l.direct_science_calls[$call].state='charged';$prefix=if($q.mode -ceq 'generated'){'direct_science_'}else{'startup_ray_original_'}
if($closed){$l[$prefix+'workers'].Remove($call);$l[$prefix+'reservations'].Remove($call);$l[$prefix+'pending_actuals'].Remove($call);if($q.mode -ceq 'original'){$l.original_jobs_running=[long]0;$l.original_reserved_s=[long]0}}
$h=K-Anchor;$values=K-Totals $l $h.policy $h.grant $state.caps;foreach($k in $values.Keys){$l[$k]=$values[$k]};$breach=$cost.cap_exceeded -or ($q.mode -ceq 'generated' -and ($l.direct_science_generated_used_s -gt $state.caps.generated_local -or $l.generated_shared_remaining_s -lt 0)) -or ($q.mode -ceq 'original' -and ($l.original_remaining_s -lt 0 -or $l.original_stage_used_s -gt 6300 -or $l.startup_ray_original_local_used_s -gt 6000))
if($closed -and $t.exit_code -ne 0){$l[$prefix+'blocking_holds'][$call]='K stage unsuccessful; successor blocked'};if($breach){K-AccountingHold $l $q.mode $call};$null=K-Validate $l;$pin=Save-Ledger $l;return @{committed=$true;cost=$costSpec;actual_s=$seconds;exit_code=$t.exit_code;ledger=$pin}
}
function K-RecoveryAction($l,$descriptor,[byte[]]$beforeRaw){
Assert-LedgerOwner $script:ledgerTransaction;Same ([Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($beforeRaw)).ToLowerInvariant()) (K-Pins).anchor.sha256 'Exact recovery raw';Same ([long]$beforeRaw.Length) (K-Pins).anchor.bytes 'Exact recovery bytes';$h=K-Recovery $descriptor;Same $l $h.anchor 'Exact whole actual baseline';$null=K-SourceFence $h.event.source_freeze;foreach($key in (Conserved-OwnerKeys)){if($key -cne 'direct_science_blocking_holds'){Same $l[$key] @{} 'No foreign/pending/unknown owners'}};Same $l.original_jobs_running ([long]0) 'No Original Job';Same $l.original_reserved_s ([long]0) 'No Original reserve';return K-RecoveredSnapshot $descriptor
}
function K-AllocationAction($l,$descriptor,[byte[]]$beforeRaw){
Assert-LedgerOwner $script:ledgerTransaction;$s=K-Validate $l;K-Eligible $l $s;Need ($s.completed -eq 1 -and -not $l.Contains((K-AllocationKey))) 'Only successful closed bootstrap allocation';$v=K-Read $descriptor;$raw=K-Raw $v.before_ledger 524288;Same ([Convert]::ToBase64String($beforeRaw)) ([Convert]::ToBase64String($raw)) 'Fresh exact raw-before allocation';$null=K-SourceFence $s.source;$e=K-Clone $l;$e[(K-AllocationKey)]=$descriptor;$caps=K-NewCaps;$e.generated_shared_cumulative_limit_s=$caps.generated_global;$e.direct_science_generated_limit_s=$caps.generated_local;$e.original_cumulative_limit_s=$caps.original_global;$h=K-Anchor;$values=K-Totals $e $h.policy $h.grant $caps;foreach($k in $values.Keys){$e[$k]=$values[$k]};$null=K-Validate $e;return $e
}
